 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_ssMarket", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ssMarket" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ssMarket")) === '1' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.psDepCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("psDepCd")) === '2610'); } }, { id: "if_ssMarket_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ssMarket" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ssMarket")) === '2' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.psDepCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("psDepCd")) === '3410'); } }, { id: "if_ssMarket_3", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ssMarket" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ssMarket")) !== '1' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ssMarket" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ssMarket")) !== '2'); } }, { id: "if_usrLdMktTpCd", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "usrLdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrLdMktTpCd")) === '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "usrLdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrLdMktTpCd")) === '2'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "usrLdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrLdMktTpCd")) === '6'); } }, { id: "if_usrLdMktTpCd", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.usrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrTpCd")) !== '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.usrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrTpCd")) !== '1'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.usrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrTpCd")) !== '1'); } }, { id: "if_usrTpCd_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.usrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("usrTpCd")) === '1'); } }, { id: "if_authYn", fn: function(){ return ((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ssMarket" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ssMarket")) === '1' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.psDepCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("psDepCd")) === '2610') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ssMarket" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ssMarket")) === '2' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.psDepCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("psDepCd")) === '3410') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ssMarket" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ssMarket")) !== '1' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ssMarket" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ssMarket")) !== '2')); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
