/**
 * @method
 * @name scwin.setEditor
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.setEditor = function (data) {
    /* sdd-asis-lifecycle:begin fn_setEditor — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (data.mktact.mktact_rsn_contn) {
        try {
            DEXT5.setBodyValue(data.mktact.mktact_rsn_contn, "dext5editor1");
        } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldstf75500' }); }
        DEXT5.setEditorChangeMode("source", "dext5editor1");
        DEXT5.setEditorChangeMode("design", "dext5editor1");
    } else {
        DEXT5.setBodyValue("", "dext5editor1");
    }
    DEXT5.setDirty("dext5editor1");
    /* sdd-asis-lifecycle:end */
};


